#!/usr/bin/env python
"""Generate the five frozen METR-LA seed-32 validation-only candidates."""

import argparse
from copy import deepcopy
from pathlib import Path

from omegaconf import OmegaConf

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "configs/paper/v4"
OUTPUT = ROOT / "configs/paper/v4_candidates/METRLA"
LF_WEIGHT = 0.05

HEADER = (
    "# GENERATED by scripts/build_v4_metrla_lf_sup_candidates.py -- do not edit.\n"
    "# METR-LA seed32 validation-only candidate; every test path is forbidden.\n"
)


def _plain(path):
    return OmegaConf.to_container(OmegaConf.load(path), resolve=True)


def _render(payload):
    return HEADER + OmegaConf.to_yaml(OmegaConf.create(payload), resolve=True)


def generated():
    graph_final = _plain(SOURCE / "experts/METRLA_ALFGraph.yaml")
    graph_legacy = deepcopy(graph_final)
    graph_legacy["runtime"]["model_variant"] = "alf_candidate_legacy5"
    graph_legacy["family"]["recipe"].update({
        "moge_support_set": "candidate_legacy5",
        "candidate_validation_only": True,
    })
    graph_sup = deepcopy(graph_final)
    graph_sup["runtime"]["model_variant"] = "alf_candidate_sup_v1"
    graph_sup["family"]["recipe"]["candidate_validation_only"] = True
    paths = {
        OUTPUT / "experts/METRLA_ALFGraph_legacy.yaml": _render(graph_legacy),
        OUTPUT / "experts/METRLA_ALFGraph_sup.yaml": _render(graph_sup),
    }

    outer = _plain(SOURCE / "METRLA_ALFNet.yaml")
    for name, use_lf, use_sup in (
        ("BASE", False, False),
        ("LF", True, False),
        ("SUP", False, True),
        ("LF_SUP", True, True),
    ):
        candidate = deepcopy(outer)
        candidate["runtime"]["model_variant"] = f"alfnet_metrla_{name.lower()}_candidate"
        recipe = candidate["family"]["recipe"]
        recipe["forecast_safe_relative_weight"] = LF_WEIGHT if use_lf else 0.0
        recipe["candidate_validation_only"] = True
        recipe["experimental_speed_safe_relative"] = bool(use_lf)
        graph_name = ("METRLA_ALFGraph_sup.yaml" if use_sup
                      else "METRLA_ALFGraph_legacy.yaml")
        candidate["family"]["experts"]["graph"]["config_path"] = (
            f"./configs/paper/v4_candidates/METRLA/experts/{graph_name}")
        paths[OUTPUT / f"{name}_ALFNet.yaml"] = _render(candidate)

    control = _plain(SOURCE / "METRLA_MoGERNN.yaml")
    control["runtime"]["model_variant"] = "mogernn_metrla_candidate_control"
    paths[OUTPUT / "CONTROL_MoGERNN.yaml"] = _render(control)
    return paths


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    failed = []
    for path, body in generated().items():
        if args.check:
            if not path.exists() or path.read_text("utf-8") != body:
                failed.append(path.relative_to(ROOT).as_posix())
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(body, "utf-8")
            print(f"wrote {path.relative_to(ROOT)}")
    if failed:
        raise SystemExit("candidate configs differ: " + ", ".join(failed))


if __name__ == "__main__":
    main()
